import json,os
from pathlib import Path
os.chdir(Path(__file__).resolve().parents[1])
rows=[
('두 다항식 A = 2x² + xy + y², B = x² + 2xy − y²에 대하여 A + B를 간단히 하면?', ['x² − xy','x² + 3xy − y²','3x² + 3xy','3x² − 3xy + y²','3x² + xy + 2y²'],2,2,'동류항을 더하면 (2x² + x²) + (xy + 2xy) + (y² − y²) = 3x² + 3xy이다.'),
('두 행렬 A = [[6, a + 1], [8, 1]], B = [[6, 4], [b − 1, 1]]에 대하여 A = B일 때, a × b의 값은? (단, a, b는 상수이다.)', ['15','18','21','24','27'],4,2,'대응 성분을 비교하면 a + 1 = 4, b − 1 = 8이다. a = 3, b = 9이므로 곱은 27이다.'),
('복소수 z = 1 + 3i의 켤레복소수가 z̄일 때, (z + z̄)i의 값은? (단, i = √−1)', ['4i','2i','0','2','4'],1,2,'z̄ = 1 − 3i이므로 z + z̄ = 2이다. 따라서 (z + z̄)i = 2i이다.'),
('등식 a(x + 2)² + 1 = 2x² + bx + 9가 x에 대한 항등식일 때, 두 상수 a, b에 대하여 a + b의 값은?', ['10','11','12','13','14'],0,3,'전개해 x²의 계수를 비교하면 a = 2이고 x의 계수에서 b = 4a = 8이다. 따라서 합은 10이다.'),
('x에 대한 이차방정식 x² + 4x + a − 5 = 0이 중근을 갖도록 하는 상수 a의 값은?', ['5','6','7','8','9'],4,3,'중근을 가지므로 판별식 16 − 4(a − 5) = 0이다. 따라서 a = 9이다.'),
('x에 대한 이차부등식 x² + ax + b ≤ 0의 해가 3 ≤ x ≤ 5일 때, 두 상수 a, b에 대하여 b − a의 값은?', ['21','22','23','24','25'],2,3,'좌변은 (x − 3)(x − 5) = x² − 8x + 15이므로 a = −8, b = 15이고 b − a = 23이다.'),
('한 개의 주사위를 두 번 던져서 나오는 눈의 수를 차례로 a, b라 하자. a² + b ≤ 6을 만족시키는 a, b의 모든 순서쌍 (a, b)의 개수는?', ['4','5','6','7','8'],3,3,'a = 1이면 b = 1, 2, 3, 4, 5로 5가지이고, a = 2이면 b = 1, 2로 2가지이다. a ≥ 3은 불가능하므로 7가지이다.'),
('행렬 A = [[−1, −2], [2, 3]]에 대하여 행렬 A² + A³의 모든 성분의 합은?', ['1','2','3','4','5'],3,3,'A² = [[−3, −4], [4, 5]], A³ = [[−5, −6], [6, 7]]이므로 A² + A³ = [[−8, −10], [10, 12]]이다. 모든 성분의 합은 4이다.'),
('다항식 x(x − 4)(x² − 4x + 7) + 12가 (x − 1)(x + a)(x + b)²으로 인수분해될 때, 두 상수 a, b에 대하여 2a + b의 값은?', ['−10','−8','−6','−4','−2'],1,3,'X = x² − 4x로 놓으면 식은 X(X + 7) + 12 = (X + 3)(X + 4) = (x − 1)(x − 3)(x − 2)²이다. 따라서 a = −3, b = −2이고 2a + b = −8이다.'),
('연립방정식 2x − y = 4, 3x² − xy − 7y = 3의 해를 x = α, y = β라 할 때, α + β의 값은?', ['8','11','14','17','20'],1,3,'y = 2x − 4를 대입하면 (x − 5)² = 0이다. 따라서 x = 5, y = 6이고 α + β = 11이다.'),
('다음 조건을 만족시키는 모든 정수 k의 개수는?<div class="mat-box">(가) x² + kx + 3k = 0이 서로 다른 두 허근을 갖는다.<br>(나) x² − 2(k − 3)x + 4k − 7 = 0이 실근을 갖는다.</div>', ['6','7','8','9','10'],0,3,'(가)의 판별식에서 0 < k < 12이고, (나)의 판별식을 4로 나누면 (k − 2)(k − 8) ≥ 0이다. 정수 k는 1, 2, 8, 9, 10, 11로 6개이다.'),
('A, B 고등학교의 남학생·여학생 수를 행렬 P = [[120, 160], [130, 140]]으로, 각 성별의 피아노·드럼 참여 비율을 Q = [[0.2, 0.8], [0.7, 0.3]]으로 나타낸다. B 고등학교에서 드럼을 배우는 모든 학생 수를 나타낸 것은?', ['행렬 PQ의 (1, 2) 성분','행렬 PQ의 (2, 1) 성분','행렬 PQ의 (2, 2) 성분','행렬 QP의 (2, 1) 성분','행렬 QP의 (2, 2) 성분'],2,3,'B 고등학교는 P의 둘째 행, 드럼 비율은 Q의 둘째 열에 해당한다. 따라서 130×0.8 + 140×0.3은 PQ의 (2, 2) 성분이다.'),
('두 이차정사각행렬 A = [[1, a], [b, −2]], B가 A + 2B = [[9, 2], [5, 0]], AB = O를 만족시킬 때, 행렬 B의 모든 성분의 합은? (단, a, b는 상수이고 O는 영행렬이다.)', ['9','10','11','12','13'],0,3,'B = (1/2)[[8, 2 − a], [5 − b, 2]]이다. AB = O의 성분을 비교하면 a = −2, b = 1이다. B = [[4, 2], [2, 1]]이므로 성분의 합은 9이다.'),
('연립부등식 |x − k| ≤ 4, x² − 11x + 18 < 0을 만족시키는 정수 x의 개수가 3이 되도록 하는 모든 정수 k의 값의 합은?', ['7','9','11','13','15'],2,4,'두 번째 부등식의 해는 2 < x < 9이다. 정수해 3부터 8 중 구간 [k − 4, k + 4]에 정확히 3개가 들어가려면 k = 1 또는 10이다. 합은 11이다.'),
('두 정수 a, b에 대하여 다항식 P(x) = x⁴ + x³ + 2x − 4, Q(x) = x⁴ + x³ + ax² + bx + 1이 모두 x + b로 나누어떨어질 때, P(b) + Q(a)의 값은?', ['−9','−7','−5','−3','−1'],3,4,'P(x) = (x − 1)(x + 2)(x² + 2)이므로 정수 b는 −1 또는 2이다. b = 2이면 Q(−2) = 0에서 a = −5/4로 정수가 아니다. b = −1이면 Q(1) = 0에서 a = −2이고 P(−1) + Q(−2) = −6 + 3 = −3이다.'),
('최고차항의 계수가 1인 이차함수 f(x)에 대하여 방정식 f(x) = 0은 서로 다른 두 실근을 갖고, 두 근의 곱은 4이다. 방정식 f(x) = −x + 1의 두 근의 차가 2일 때, f(6)의 값은?', ['7','10','13','16','19'],1,4,'f(x) = x² + ax + 4라 하면 f(x) = −x + 1의 두 근의 차가 2이므로 (a + 1)² − 12 = 4이다. a = 3 또는 −5인데 f(x) = 0이 서로 다른 두 실근을 갖는 것은 a = −5이다. 따라서 f(6) = 10이다.'),
('이차항의 계수가 3인 이차함수 f(x)와 일차항의 계수가 12인 일차함수 g(x)가 다음 조건을 만족시킬 때, f(3)의 값은?<div class="mat-box">(가) f(0) − g(0) = f(2) − g(2) = 3<br>(나) 방정식 f(x) + g(x) = 0이 중근을 갖는다.</div>', ['48','51','54','57','60'],4,4,'(가)에서 f(x) − g(x) = 3x(x − 2) + 3이다. g(x) = 12x + a라 하면 f(x) + g(x) = 3x² + 18x + 2a + 3이다. 판별식을 0으로 놓으면 a = 12이고 f(3) = 60이다.'),
('삼차방정식 x³ − 6x² + (k + 8)x − 2k = 0은 서로 다른 세 실근 α, β, γ (α < β < γ)를 갖는다. 2α + β = 2γ일 때, 상수 k의 값은?', ['27/8','7/2','29/8','15/4','31/8'],3,4,'좌변은 (x − 2)(x² − 4x + k)로 인수분해된다. 두 이차식의 근의 평균이 2이므로 β = 2이고 α + γ = 4이다. 2α + 2 = 2γ에서 γ − α = 1이므로 α = 3/2, γ = 5/2이고 k = αγ = 15/4이다.'),
('두 양수 a, b에 대하여 이차함수 f(x) = a(x − b)²이 있다. 실수 k에 대하여 k ≤ x ≤ k + 2에서 f(x)의 최댓값과 최솟값의 차를 g(k)라 할 때, g(3) = a, g(2) + g(6) = 32이다. f(6)의 값은?', ['8','9','10','11','12'],0,4,'구간 [3, 5]에서 이차함수의 범위가 a가 되려면 꼭짓점이 가운데인 b = 4이다. 이때 g(2) = 4a, g(6) = 12a이므로 16a = 32, a = 2이다. f(6) = 2(6 − 4)² = 8이다.'),
('최고차항의 계수가 a (a < 0)인 두 이차함수 f(x), g(x)에 대하여 f(3) = g(3)이다. h(x) = f(x) (x ≤ 3), h(x) = g(x) (x > 3)이고 다음을 만족시킨다.<div class="mat-box">(가) y = h(x)의 그래프와 직선 y = f(0)이 만나는 점의 x좌표는 0, 4, 12뿐이다.<br>(나) 두 실수 α, β (α < 3 < β)에 대해 y = h(x)의 그래프와 직선 y = 2x − 8이 만나는 점의 x좌표는 α, 3, β이다.</div>α + β = 6일 때 h(−2) + h(5)의 값은?', ['15','16','17','18','19'],2,4,'f(0) = b라 하면 조건 (가)와 f(3) = g(3)에서 f(x) = ax² + b, g(x) = a(x − 4)(x − 12) + b이다. 직선과의 교점에 근과 계수의 관계를 적용하면 α + 3 = 2/a, 3 + β = 16 + 2/a이다. α + β = 6에서 a = −1이고, x = 3 대입으로 b = 7이다. 따라서 h(−2) = 3, h(5) = 14이므로 합은 17이다.'),
('월요일부터 금요일까지 5일 동안 서로 다른 네 종목 A, B, C, D 중 매일 서로 다른 두 종목씩 빠짐없이 활동하려고 한다. 다음 규칙에 따라 스포츠 활동 신청서를 작성하는 경우의 수는? (단, 종목을 신청하는 순서는 고려하지 않는다.)<div class="mat-box">(가) 각 종목은 적어도 2일 활동한다.<br>(나) A와 B는 같은 요일에 활동하지 않는다.<br>(다) B와 C는 하루만 같은 요일에 활동한다.</div>', ['410','420','430','440','450'],4,4,'A와 B의 활동일을 먼저 고른다. 조건상 (A일수, B일수)는 (2,2), (2,3), (3,2)이다. 각각의 경우 나머지 C, D 배치까지 세면 240, 90, 120가지이다. 따라서 총 450가지이다.')]
assert len(rows)==21
items=[dict(q=q,choices=choices,correct=correct,points=points,explain=explain,fixed=True,source=f'2025년 9월 고1 {i}번') for i,(q,choices,correct,points,explain) in enumerate(rows,1)]
v=json.loads(Path('math/variants.json').read_text())
for r in [q for q in v if q['course']==1][:4]:
 ans=int(r['answer']);items.append(dict(q=r['problem'],choices=[str(ans-2),str(ans-1),str(ans),str(ans+1),str(ans+2)],correct=2,points=2,explain=r['explanation'],source='기출 유형 변형'))
assert len(items)==25
Path('math/transcriptions/2025-09-text.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
Path('math/transcribed-2025-09.js').write_text('window.SEOIK_2025_09_TEXT = '+json.dumps(items,ensure_ascii=False,separators=(',',':'))+';\n')
